"""Original missing data-model labs; register as optional ordered source branches."""
SPECS = [
    dict(key='special-method-lookup',title='Implicit special methods use the type',
         explanation='An implicit special operation such as len(obj) resolves its special method on the type. An ordinary explicit attribute lookup on that instance can observe a different attribute.',
         pitfall='Changing an instance attribute named __len__ does not redefine the implicit len protocol.',
         body="class Window:\n    def __init__(self, items):\n        self.items = tuple(items)\n    def __len__(self):\n        return len(self.items)\nwindow = Window(data)\nwindow.__len__ = lambda: 99\nresult = [len(window), window.__len__()]",
         cases=[([],[0,99]),([2,5],[2,99]),([7],[1,99])],
         mutation=('return len(self.items)','return len(self.items) + 1'),imports=''),
    dict(key='sequence-protocol',title='A small sequence can support familiar operations',
         explanation='A read-only sequence can supply __len__ and __getitem__, delegating indexing and slicing to its owned tuple. Iteration and membership can fall back to the sequence protocol without a custom __iter__.',
         pitfall='Changing the returned element changes iteration, membership and slicing together; syntax support is a behavioral contract.',
         body="class Readings:\n    def __init__(self, items):\n        self._items = tuple(items)\n    def __len__(self):\n        return len(self._items)\n    def __getitem__(self, key):\n        return self._items[key]\nitems, probe = data\nwindow = Readings(items)\nresult = [len(window), list(window), list(window[::-1]), probe in window]",
         cases=[([[2,5,9],5],[3,[2,5,9],[9,5,2],True]),([[],1],[0,[],[],False]),([[0,-2],4],[2,[0,-2],[-2,0],False])],
         mutation=('return self._items[key]','return self._items[key] * 2'),imports=''),
    dict(key='object-representation',title='Separate diagnostic representation from display text',
         explanation='repr(obj) should give an unambiguous diagnostic representation. str(obj) supplies user-facing text, and an empty-format f-string uses that display representation.',
         pitfall='Dropping repr conversion for text fields removes quoting and escape information needed to distinguish their contents.',
         body="class Label:\n    def __init__(self, text):\n        self.text = text\n    def __repr__(self):\n        return f'Label({self.text!r})'\n    def __str__(self):\n        return self.text\nlabel = Label(data)\nresult = [repr(label), str(label), f'{label}']",
         cases=[('x',["Label('x')",'x','x']),('line\nnext',["Label('line\\nnext')",'line\nnext','line\nnext']),('',["Label('')",'',''])],
         mutation=("f'Label({self.text!r})'","f'Label({self.text})'"),imports=''),
    dict(key='truth-protocol',title='Define truth from the domain contract',
         explanation='A custom __bool__ returns a Boolean describing the domain. Numeric zero can be false while negative nonzero values remain true; positivity and truth are different predicates.',
         pitfall='Using greater-than-zero misclassifies a valid negative nonzero amount as false.',
         body="class Delta:\n    def __init__(self, amount):\n        self.amount = amount\n    def __bool__(self):\n        return self.amount != 0\nresult = bool(Delta(data))",
         cases=[(0,False),(4,True),(-2,True)],
         mutation=('self.amount != 0','self.amount > 0'),imports=''),
    dict(key='numeric-dispatch',title='Return NotImplemented to permit operator fallback',
         explanation='An unsupported binary operation can return NotImplemented so Python can try the other operand’s reflected operation. This differs from raising TypeError immediately, and from returning a fabricated result.',
         pitfall='Raising before dispatch fallback prevents a compatible right operand from handling the operation.',
         body="class Step:\n    def __init__(self, value):\n        self.value = value\n    def __add__(self, other):\n        if not isinstance(other, Step):\n            return NotImplemented\n        return Step(self.value + other.value)\n    def __abs__(self):\n        return abs(self.value)\nclass Offset:\n    def __radd__(self, left):\n        if isinstance(left, Step):\n            return left.value + 10\n        return NotImplemented\na, b = Step(data[0]), Step(data[1])\ncombined = a + b\ntry:\n    a + 'unsupported'\n    rejected = False\nexcept TypeError:\n    rejected = True\nresult = [combined.value, a.value, b.value, abs(a), a + Offset(), rejected]",
         cases=[([3,-2],[1,3,-2,3,13,True]),([-4,0],[-4,-4,0,4,6,True]),([0,0],[0,0,0,0,10,True])],
         mutation=('return NotImplemented',"raise TypeError('unsupported')"),imports=''),
    dict(key='magnitude-protocol',title='Use abs with a domain magnitude',
         explanation='A numeric-like object can implement __abs__ to return its magnitude. For a pair of orthogonal components, hypot computes Euclidean magnitude; truth can then explicitly use whether that magnitude is nonzero.',
         pitfall='Adding signed components is not a magnitude and can cancel nonzero components incorrectly.',
         body="class Components:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n    def __abs__(self):\n        return math.hypot(self.x, self.y)\n    def __bool__(self):\n        return bool(abs(self))\nvalue = Components(*data)\nresult = [abs(value), bool(value)]",
         cases=[([3,4],[5.0,True]),([0,0],[0.0,False]),([-3,4],[5.0,True])],
         mutation=('math.hypot(self.x, self.y)','self.x + self.y'),imports='import math'),
]

def register(add):
    for spec in SPECS:
        add(6, spec['key'], spec['title'], spec['explanation'], spec['pitfall'],
            spec['body'], spec['cases'], spec['mutation'], spec['imports'], supplemental=True)
